namespace RonSijm.FluidHumidifier.Factories.EventsV2;

public class SubscriberFactory(string resourceName = null, Action<Humidifier.EventsV2.Subscriber> factoryAction = null) : ResourceFactory<Humidifier.EventsV2.Subscriber>(resourceName)
{

    internal InnerSubscriberTransformerFactory TransformerFactory { get; set; }

    internal InnerSubscriberBatchConfigurationFactory BatchConfigurationFactory { get; set; }

    internal InnerSubscriberInvokeConfigurationFactory InvokeConfigurationFactory { get; set; }

    internal InnerSubscriberFilterConfigurationFactory FilterConfigurationFactory { get; set; }

    internal InnerSubscriberOnFailureConfigurationFactory OnFailureConfigurationFactory { get; set; }

    internal InnerSubscriberLogConfigurationFactory LogConfigurationFactory { get; set; }

    internal InnerSubscriberPointInTimeConfigurationFactory PointInTimeConfigurationFactory { get; set; }

    internal InnerSubscriberRetryPolicyFactory RetryPolicyFactory { get; set; }

    protected override Humidifier.EventsV2.Subscriber Create()
    {
        var subscriberResult = CreateSubscriber();
        factoryAction?.Invoke(subscriberResult);

        return subscriberResult;
    }

    private Humidifier.EventsV2.Subscriber CreateSubscriber()
    {
        var subscriberResult = new Humidifier.EventsV2.Subscriber
        {
            GivenName = InputResourceName,
        };

        return subscriberResult;
    }
    public override void CreateChildren(Humidifier.EventsV2.Subscriber result)
    {
        base.CreateChildren(result);

        result.Transformer ??= TransformerFactory?.Build();
        result.BatchConfiguration ??= BatchConfigurationFactory?.Build();
        result.InvokeConfiguration ??= InvokeConfigurationFactory?.Build();
        result.FilterConfiguration ??= FilterConfigurationFactory?.Build();
        result.OnFailureConfiguration ??= OnFailureConfigurationFactory?.Build();
        result.LogConfiguration ??= LogConfigurationFactory?.Build();
        result.PointInTimeConfiguration ??= PointInTimeConfigurationFactory?.Build();
        result.RetryPolicy ??= RetryPolicyFactory?.Build();
    }

} // End Of Class

